<?php
declare(strict_types=1);
namespace Tests\Unit\QuestionLearning;
use App\Application\QuestionLearning\Service\GetLearningSignalAggregateService;use App\Domain\QuestionLearning\Entity\LearningEvent;use App\Domain\QuestionLearning\Enum\LearningEventType;use App\Domain\QuestionLearning\Enum\LearningOutcome;use App\Domain\QuestionLearning\Repository\LearningEventRepositoryInterface;use PHPUnit\Framework\TestCase;
final class GetLearningSignalAggregateServiceTest extends TestCase { public function testAggregatesOnlyOwnSubjectSignals(): void { $repo=new class implements LearningEventRepositoryInterface { public function append(LearningEvent $event):void{} public function listForUserSubject(string $u,string $s,\DateTimeImmutable $since):array{return [new LearningEvent('1',$u,'q','a',$s,LearningEventType::ANSWER_COMPLETED,LearningOutcome::CORRECT,10,'STUDY',[],$since),new LearningEvent('2',$u,'q',null,$s,LearningEventType::NOT_MASTERED_ENABLED,null,null,'QUESTION_INTERACTION',[],$since)];} };$aggregate=(new GetLearningSignalAggregateService($repo))->execute('user-1','subject-1',new \DateTimeImmutable());self::assertSame(1,$aggregate->answerCount);self::assertSame(1,$aggregate->correctCount);self::assertSame(1,$aggregate->notMasteredActivations); } }
